let particles = [];
let gravity = 0.15;
let friction = 0.99;
let mouseMode = 'attract'; // 'attract', 'repel', 'spawn'
let trails = true;
let showInfo = true;
let colorMode = 'rainbow'; // 'rainbow', 'fire', 'ocean'

function setup() {
  createCanvas(windowWidth, windowHeight);
  for (let i = 0; i < 150; i++) {
    particles.push(new Particle(random(width), random(height)));
  }
  textAlign(CENTER, CENTER);
}

function draw() {
  // Fade background for trails effect
  if (trails) {
    fill(0, 0, 0, 40);
    noStroke();
    rect(0, 0, width, height);
  } else {
    background(10);
  }

  // Mouse interaction
  let mouseForce = createVector(0, 0);
  let range = 250;

  for (let p of particles) {
    let d = dist(mouseX, mouseY, p.pos.x, p.pos.y);

    if (mouseIsPressed && mouseMode !== 'spawn') {
      if (d < range) {
        let force = p5.Vector.sub(createVector(mouseX, mouseY), p.pos);
        force.normalize();
        let strength = map(d, 0, range, 2, 0);
        if (mouseMode === 'repel') {
          force.mult(-strength);
        } else {
          force.mult(strength);
        }
        p.applyForce(force);
      }
    }

    p.update();
    p.display();
  }

  // Draw cursor indicator
  noFill();
  stroke(255, 100);
  strokeWeight(2);
  if (mouseMode === 'attract') {
    ellipse(mouseX, mouseY, range);
    fill(100, 255, 100);
    noStroke();
    ellipse(mouseX, mouseY, 8);
  } else if (mouseMode === 'repel') {
    ellipse(mouseX, mouseY, range);
    stroke(255, 100, 100);
    strokeWeight(2);
    line(mouseX - 6, mouseY, mouseX + 6, mouseY);
    line(mouseX, mouseY - 6, mouseX, mouseY + 6);
  } else if (mouseMode === 'spawn') {
    fill(100, 200, 255);
    noStroke();
    ellipse(mouseX, mouseY, 12);
  }

  // UI Overlay
  if (showInfo) {
    drawUI();
  }
}

function mousePressed() {
  if (mouseMode === 'spawn') {
    for (let i = 0; i < 5; i++) {
      let p = new Particle(mouseX + random(-10, 10), mouseY + random(-10, 10));
      p.vel = p5.Vector.random2D().mult(random(2, 6));
      particles.push(p);
    }
    if (particles.length > 400) {
      particles.splice(0, 5);
    }
  }
}

function keyPressed() {
  if (key === '1') mouseMode = 'attract';
  if (key === '2') mouseMode = 'repel';
  if (key === '3') mouseMode = 'spawn';
  if (key === 'g' || key === 'G') gravity = gravity === 0 ? 0.15 : 0;
  if (key === 't' || key === 'T') trails = !trails;
  if (key === 'c' || key === 'C') {
    if (colorMode === 'rainbow') colorMode = 'fire';
    else if (colorMode === 'fire') colorMode = 'ocean';
    else colorMode = 'rainbow';
  }
  if (key === 'r' || key === 'R') {
    particles = [];
    for (let i = 0; i < 150; i++) {
      particles.push(new Particle(random(width), random(height)));
    }
  }
  if (key === 'h' || key === 'H') showInfo = !showInfo;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function drawUI() {
  push();
  fill(0, 0, 0, 180);
  noStroke();
  rect(20, 20, 280, 200, 10);

  fill(255);
  textAlign(LEFT, TOP);
  textSize(16);
  text("🎮 Interactive Particle Sim", 35, 35);

  textSize(12);
  let y = 65;
  let lh = 18;
  text("1 - Attract Mode (default)", 35, y); y += lh;
  text("2 - Repel Mode", 35, y); y += lh;
  text("3 - Spawn Mode (click to spawn)", 35, y); y += lh;
  text("G - Toggle Gravity", 35, y); y += lh;
  text("T - Toggle Trails", 35, y); y += lh;
  text("C - Cycle Colors (Rainbow/Fire/Ocean)", 35, y); y += lh;
  text("R - Reset Simulation", 35, y); y += lh;
  text("H - Toggle this Help", 35, y); y += lh;

  fill(200);
  text("Particles: " + particles.length + " | Mode: " + mouseMode.toUpperCase(), 35, y + 5);
  pop();
}

class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(1, 3));
    this.acc = createVector(0, 0);
    this.size = random(3, 8);
    this.baseSize = this.size;
    this.hueOffset = random(360);
  }

  applyForce(force) {
    this.acc.add(force);
  }

  update() {
    // Apply gravity
    if (gravity > 0) {
      this.applyForce(createVector(0, gravity));
    }

    this.vel.add(this.acc);
    this.vel.mult(friction);
    this.pos.add(this.vel);
    this.acc.mult(0);

    // Bounce off walls
    if (this.pos.x < this.size) {
      this.pos.x = this.size;
      this.vel.x *= -0.8;
    }
    if (this.pos.x > width - this.size) {
      this.pos.x = width - this.size;
      this.vel.x *= -0.8;
    }
    if (this.pos.y < this.size) {
      this.pos.y = this.size;
      this.vel.y *= -0.8;
    }
    if (this.pos.y > height - this.size) {
      this.pos.y = height - this.size;
      this.vel.y *= -0.6;
      if (abs(this.vel.y) < 1) this.vel.y = 0;
    }

    // Dynamic size based on speed
    let speed = this.vel.mag();
    this.size = lerp(this.size, this.baseSize + speed * 0.5, 0.1);
  }

  display() {
    noStroke();

    let speed = this.vel.mag();
    let hueVal, sat, bri;

    if (colorMode === 'rainbow') {
      hueVal = (this.hueOffset + frameCount * 2 + speed * 30) % 360;
      sat = 80;
      bri = map(speed, 0, 8, 60, 100, true);
    } else if (colorMode === 'fire') {
      hueVal = map(speed, 0, 8, 10, 50);
      sat = 90;
      bri = map(speed, 0, 8, 60, 100, true);
    } else {
      hueVal = map(speed, 0, 8, 180, 220);
      sat = 80;
      bri = map(speed, 0, 8, 50, 100, true);
    }

    if (trails) {
      // Glow effect
      for (let i = 3; i > 0; i--) {
        fill(hueVal, sat, bri, 15);
        ellipse(this.pos.x, this.pos.y, this.size * (1 + i * 0.8));
      }
    }

    fill(hueVal, sat, bri);
    ellipse(this.pos.x, this.pos.y, this.size);
  }
}

